import{_ as r,o as e,c as a,a3 as d}from"./chunks/framework.CWYzGJW1.js";const b=JSON.parse('{"title":"硬體價格","description":"各硬體選項的參考價格與規格, 以單機同時常駐 3 個約 35B 模型為情境估算預算; 價格變動快, 採購前請以當月報價為準.","frontmatter":{"description":"各硬體選項的參考價格與規格, 以單機同時常駐 3 個約 35B 模型為情境估算預算; 價格變動快, 採購前請以當月報價為準."},"headers":[],"relativePath":"ref/hardware-prices.md","filePath":"ref/hardware-prices.md","lastUpdated":1793060541000}'),l={name:"ref/hardware-prices.md"};function o(i,t,n,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="硬體價格" tabindex="-1">硬體價格 <a class="header-anchor" href="#硬體價格" aria-label="Permalink to &quot;硬體價格&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: 參考資料</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 台灣現價多數查無, 本頁以美元價為主並標示日期與性質; 部分價格為媒體轉引的二手來源; 主機其他零組件未查價; 價格變動快, 引用前請以當月報價為準</li></ul></div><p><strong>結論</strong>: 單機同時常駐 3 個約 35B 的模型, 僅計 GPU 或整機本體的預算, 入門約 3,100 至 8,000 美元 (統一記憶體機種, 以 MoE 模型為主), 標準約 11,360 至 16,000 美元 (1 張 96GB 的 RTX PRO 6000), 進階約 22,720 至 32,000 美元 (2 張 RTX PRO 6000). 這些價格不含主機其他零組件, 且 2026 年 DRAM 與 GDDR7 漲價使各選項價格明顯上升 (信心: 高, 依據為 TrendForce 的 DRAM 與 GDDR7 價格報告); 表中多個品項的官方通路標示缺貨 (信心: 中, 依據為表中各列的來源). 配置的選擇邏輯見 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a>.</p><p>價格表中的統一記憶體機種, 指 CPU 與 GPU 共用同一池記憶體的整機; MoE (Mixture of Experts, 混合專家) 模型每次只啟用一部分參數, 對記憶體頻寬的需求較低, 因此常搭配這類機種 (見 <a href="/lanai-handbook/know/k3-hardware">K3</a>). DRAM 是一般電腦的主記憶體, GDDR7 是新一代顯示卡使用的記憶體, 兩者的漲價都直接反映在硬體售價上.</p><p>表中品項依角色分為兩類. 第一類是插在主機裡負責模型運算的顯示卡: RTX PRO 系列是 NVIDIA 的工作站顯示卡, GeForce RTX 系列是消費級顯示卡, Radeon AI PRO 是 AMD 的工作站顯示卡. 第二類是本身就是一台完整電腦的統一記憶體整機: DGX Spark 與各廠的 GB10 機種採用 NVIDIA GB10 晶片, Strix Halo 迷你主機與 Framework Desktop 採用 AMD 整合 CPU 與 GPU 的晶片, Mac Studio 是 Apple 的桌上型電腦.</p><h2 id="查價說明" tabindex="-1">查價說明 <a class="header-anchor" href="#查價說明" aria-label="Permalink to &quot;查價說明&quot;">​</a></h2><ul><li><strong>台灣現價</strong>: 本輪查證台灣的 RTX PRO 6000, RTX 5090, DGX Spark 現價皆查無公開資料; 下表以美元價為主, 台灣價只列查得到的項目並標示來源.</li><li><strong>價格性質</strong>: 「官方掛牌」指廠商官方商店的標價, 缺貨時不代表買得到; 「通路價」指零售或經銷商標價; 「二手刊登價」不是成交價; 「次級來源」指媒體或部落格轉引.</li><li><strong>幣別</strong>: 除註明新台幣 (NT$) 外一律為美元. 本頁不做匯率換算, 請依購買當日匯率自行換算.</li></ul><h2 id="價格表" tabindex="-1">價格表 <a class="header-anchor" href="#價格表" aria-label="Permalink to &quot;價格表&quot;">​</a></h2><h3 id="nvidia-工作站與消費級顯示卡" tabindex="-1">NVIDIA 工作站與消費級顯示卡 <a class="header-anchor" href="#nvidia-工作站與消費級顯示卡" aria-label="Permalink to &quot;NVIDIA 工作站與消費級顯示卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>品項</th><th>價格</th><th>查價日期</th><th>性質與來源</th></tr></thead><tbody><tr><td>RTX PRO 6000 Blackwell Workstation</td><td>16,000 (缺貨)</td><td>2026-08-12</td><td>官方商店掛牌, 非正式建議售價 (letsdatascience 轉引 PCMag 與 Tom&#39;s Hardware)</td></tr><tr><td>同上</td><td>13,250</td><td>2026-06-13</td><td>NVIDIA 商店 (IT之家轉引 Tom&#39;s Hardware, 二手來源); 上市價 8,565 (2025-03)</td></tr><tr><td>同上 (PNY / Newegg 通路)</td><td>11,359.99 / 12,099.99</td><td>2026-06-13</td><td>通路價 (IT之家, 二手來源)</td></tr><tr><td>RTX PRO 6000 Blackwell Server Edition</td><td>14,999</td><td>2026-06-13</td><td>通路價 (IT之家, 二手來源)</td></tr><tr><td>RTX PRO 6000 台灣</td><td>現價查無; 2025 年上市前傳聞散裝約 NT$200,000, 盒裝約 NT$270,000</td><td>2025</td><td>已過時, 僅供對照 (Techbang)</td></tr><tr><td>RTX PRO 5000 Blackwell 48GB</td><td>4,199.99 (上市刊價); 二手最低三筆均價 7,040</td><td>2025-12-28; 2026-10</td><td>前者通路 (TechRadar), 後者二手 (GPU Poet); 兩者差距大</td></tr><tr><td>RTX PRO 5000 72GB</td><td>價格查無</td><td>-</td><td>-</td></tr><tr><td>RTX PRO 4500 Blackwell 32GB</td><td>6,209 (建議售價 5,499)</td><td>日期查無</td><td>通路 (SHI)</td></tr><tr><td>GeForce RTX 5090 32GB</td><td>新品 4,288 至 4,381; 二手刊登 3,590 至 4,304 (建議售價 1,999)</td><td>2026-08-07 至 08</td><td>刊登價非成交價 (BuySellRAM)</td></tr><tr><td>同上 (美國網購第三方賣家)</td><td>6,500 至 9,500 開價 (官方通路缺貨)</td><td>2026-09-16</td><td>次級來源, 開價非成交價; 文中的新台幣金額為美元換算, 不是台灣售價 (科技新報)</td></tr><tr><td>RTX 3090 二手</td><td>1,095 至 1,181 (8 月); 1,200 至 1,400 (9 月)</td><td>2026-08 至 09</td><td>二手刊登價 (BuySellRAM; OpenClawDC)</td></tr><tr><td>RTX 4090 二手</td><td>2,350 至 2,500</td><td>2026-08 至 09</td><td>二手刊登價 (InsiderLLM)</td></tr></tbody></table><h3 id="統一記憶體整機" tabindex="-1">統一記憶體整機 <a class="header-anchor" href="#統一記憶體整機" aria-label="Permalink to &quot;統一記憶體整機&quot;">​</a></h3><table tabindex="0"><thead><tr><th>品項</th><th>價格</th><th>查價日期</th><th>性質與來源</th></tr></thead><tbody><tr><td>DGX Spark 128GB</td><td>6,950 (缺貨); 上市價 3,999, 2026-02 調為 4,699</td><td>2026-10-02</td><td>官方 Marketplace 掛牌 (The Register; implicator; 三處交叉)</td></tr><tr><td>DGX Spark 64GB</td><td>起價 4,999, 10 月 23 日起僅經 Acer, ASUS, Dell, Gigabyte, HP, MSI 供應</td><td>2026-10-02</td><td>NVIDIA 公告 (The Register)</td></tr><tr><td>GB10 OEM 機種</td><td>ASUS GX10 5,999 (1TB) / 7,999 (4TB), 皆缺貨; Dell 5,903; Lenovo 起 5,859; MSI EdgeXpert 7,999; Acer GN100 4,699.99 (缺貨)</td><td>2026-10-16</td><td>美國通路 (issoh)</td></tr><tr><td>ASUS GX10 台灣</td><td>NT$97,900 起, 接單生產; 現價查無</td><td>2025-10-15</td><td>已過時 (Techbang)</td></tr><tr><td>Mac Studio M5 Max / M5 Ultra (美國)</td><td>M5 Max 起 2,499; M5 Ultra 起 5,499; 256GB 加 16TB 為 18,299</td><td>2026-08-25</td><td>官方建議售價 (Macworld)</td></tr><tr><td>Mac Studio M5 (台灣)</td><td>M5 Max 起 NT$84,900; M5 Ultra 起 NT$199,900; 512GB 價格查無</td><td>2026-09-02</td><td>次級來源 (mrmad); Apple 台灣規格頁抓取時未顯示價格</td></tr><tr><td>Mac Studio M3 Ultra</td><td>512GB 選項已於 2026-03 停售, 最高 256GB; 現是否仍在售查無</td><td>2026-03-06</td><td>Notebookcheck 轉引 MacRumors</td></tr><tr><td>Strix Halo 128GB 迷你主機</td><td>BOSGAME M5 約 3,100; Beelink GTR9 Pro 約 4,350; Minisforum MS-S1 MAX 3,799; GMKtec EVO-X3 3,799.99</td><td>2026-09</td><td>通路 (starryhope); EVO-X2 現價查無</td></tr><tr><td>Framework Desktop 128GB</td><td>2,459 (較前調漲 460); 現價查無</td><td>2026-01-13</td><td>官方調價 (Notebookcheck)</td></tr><tr><td>Radeon AI PRO R9700 32GB</td><td>約 1,950 (經銷商); 上市約 1,299</td><td>2026-10</td><td>次級來源 (ComputingForGeeks; Club386)</td></tr></tbody></table><h2 id="_3-個-35b-級模型的配置預算" tabindex="-1">3 個 35B 級模型的配置預算 <a class="header-anchor" href="#_3-個-35b-級模型的配置預算" aria-label="Permalink to &quot;3 個 35B 級模型的配置預算&quot;">​</a></h2><p>表中的 FP8 是以 8 位元浮點數存放權重的格式, 品質接近原始的 16 位元, 但記憶體需求約為 4 位元量化的兩倍 (見 <a href="/lanai-handbook/know/k2-quantization">K2</a>). 以下為上表價格的算術加總, 僅含 GPU 或整機本體, 不含 CPU, 主機板, 系統記憶體, 電源, 機箱與儲存 (這些項目未查價, 系統記憶體同樣受 DRAM 漲價影響). 配置的容量與頻寬分析見 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a>.</p><table tabindex="0"><thead><tr><th>檔位</th><th>配置</th><th>價格區間 (美元)</th><th>算式</th><th>適用</th></tr></thead><tbody><tr><td>入門</td><td>GB10 整機或 Strix Halo 128GB, 3 個 MoE 模型的 4 位元</td><td>約 3,100 至 8,000</td><td>Strix Halo 3,100 至 4,350; GB10 OEM 4,699.99 至 7,999</td><td>個人或 2 至 3 人 PoC, 同時使用人數少</td></tr><tr><td>標準</td><td>1 張 RTX PRO 6000 (96GB), 4 位元量化</td><td>11,360 至 16,000 (卡本體)</td><td>PNY 11,359.99 (2026-06) 至官方掛牌 16,000 (2026-08, 缺貨)</td><td>小團隊日常使用</td></tr><tr><td>進階</td><td>2 張 RTX PRO 6000, FP8</td><td>22,720 至 32,000 (卡本體)</td><td>標準檔的 2 倍</td><td>要 FP8 品質, 長上下文, 或較多人同時使用</td></tr><tr><td>大容量統一記憶體</td><td>Mac Studio M5 Ultra</td><td>5,499 起; 256GB 加 16TB 為 18,299</td><td>官方建議售價 (美國); 台灣 M5 Ultra 起 NT$199,900 (次級來源)</td><td>容量需求大, 並行需求低到中</td></tr></tbody></table><p>這些區間只涵蓋地端硬體. 雲端模型的 API 費用依用量計算, 不在本頁範圍.</p><h2 id="價格為什麼波動" tabindex="-1">價格為什麼波動 <a class="header-anchor" href="#價格為什麼波動" aria-label="Permalink to &quot;價格為什麼波動&quot;">​</a></h2><ul><li>TrendForce (追蹤記憶體與半導體價格的市場研究機構) 2026-09-30 的報導指出, 2026 年第 4 季一般 DRAM 合約價季增 10% 至 15%, GDDR7 持續上行, 原因是 AI 晶片採購壓縮 GDDR7 產能.</li><li>TrendForce 2026-08-04 的報導指出, 韓國 RTX 50 系列 8 月最多漲 30%, 2026 年 DRAM 供給缺口約 1% 至 2%, 2027 年擴大.</li><li>整機實例: DGX Spark 128GB 自 3,999 調到 6,950 (約 +75%, The Register 歸因於記憶體成本); RTX PRO 6000 自上市價 8,565 到掛牌價 16,000.</li><li>因應方向: 引用價格時標註查價日期, 採購前以當月報價為準; 預算有彈性時, 可先以較低檔位驗證需求 (M1, M6), 再決定是否升級.</li></ul><h2 id="更新紀錄" tabindex="-1">更新紀錄 <a class="header-anchor" href="#更新紀錄" aria-label="Permalink to &quot;更新紀錄&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>內容</th></tr></thead><tbody><tr><td>2026-10-26</td><td>首次建立: NVIDIA 工作站與消費級顯示卡, 統一記憶體整機, 3 個 35B 級模型的配置預算</td></tr></tbody></table><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>官方與廠商公告:</p><ul><li><a href="https://www.nvidia.com/en-us/products/workstations/professional-desktop-gpus/rtx-pro-6000-family/" target="_blank" rel="noreferrer">NVIDIA: RTX PRO 6000 Blackwell 家族</a></li><li><a href="https://www.nvidia.com/en-us/products/workstations/professional-desktop-gpus/rtx-pro-5000/" target="_blank" rel="noreferrer">NVIDIA: RTX PRO 5000 Blackwell</a></li><li><a href="https://www.apple.com/tw/mac-studio/specs/" target="_blank" rel="noreferrer">Apple: Mac Studio 技術規格</a></li><li><a href="https://www.trendforce.com/presscenter/news/20260930-13258.html" target="_blank" rel="noreferrer">TrendForce 新聞稿 (2026-09-30)</a></li><li><a href="https://www.trendforce.com/news/2026/08/04/news-nvidia-rtx-50-prices-in-korea-may-rise-up-to-30-from-aug-on-higher-tsmc-wafer-and-gddr7-memory-costs/" target="_blank" rel="noreferrer">TrendForce: NVIDIA RTX 50 價格在韓國 8 月可能上漲最多 30% (2026-08-04)</a></li></ul><p>媒體與通路 (二手來源):</p><ul><li><a href="https://letsdatascience.com/news/nvidia-raises-rtx-pro-6000-blackwell-price-again-6d1ae9ff" target="_blank" rel="noreferrer">letsdatascience: NVIDIA raises RTX PRO 6000 Blackwell price again</a></li><li><a href="https://www.ithome.com/0/963/977.htm" target="_blank" rel="noreferrer">IT之家 (ithome.com, 非台灣的 iThome): RTX PRO 6000 價格報導 (二手來源, 轉引 Tom&#39;s Hardware)</a></li><li><a href="https://techspot.com/news/113460-nvidia-raises-rtx-pro-6000-blackwell-price-staggering.html" target="_blank" rel="noreferrer">TechSpot: NVIDIA raises RTX PRO 6000 Blackwell price</a></li><li><a href="https://hao.cnyes.com/post/263122" target="_blank" rel="noreferrer">鉅亨: RTX PRO 6000 價格報導</a></li><li><a href="https://www.techbang.com/posts/122132-nvidia-blackwellrtx-pro-6000" target="_blank" rel="noreferrer">Techbang: NVIDIA Blackwell RTX PRO 6000</a></li><li><a href="https://technews.tw/2026/09/16/rtx-5090-price-past-190000/" target="_blank" rel="noreferrer">科技新報: RTX 5090 價格</a></li><li><a href="https://www.techbang.com/posts/132927-nvidia-rtx-50-series-price-surge-rtx-5090" target="_blank" rel="noreferrer">Techbang: RTX 50 系列價格上漲</a></li><li><a href="https://www.buysellram.com/blog/nvidia-consumer-gpu-price-report-august-2026/" target="_blank" rel="noreferrer">BuySellRAM: NVIDIA consumer GPU price report (2026-08)</a></li><li><a href="https://openclawdc.com/blog/how-to-buy-a-used-rtx-3090-safely/" target="_blank" rel="noreferrer">OpenClawDC: 二手 RTX 3090</a></li><li><a href="https://insiderllm.com/guides/multi-gpu-local-ai/" target="_blank" rel="noreferrer">InsiderLLM: multi-GPU local AI</a></li><li><a href="https://www.techradar.com/pro/great-news-nvidia-finally-has-a-72gb-graphics-card-but-since-its-the-rtx-pro-5000-blackwell-it-will-probably-cost-you-just-a-bit-more-than-a-64gb-ddr5-stick-sarcasm" target="_blank" rel="noreferrer">TechRadar: RTX PRO 5000 72GB</a></li><li><a href="https://gpupoet.com/gpu/learn/price/october-2026/nvidia-rtx-pro-5000-blackwell" target="_blank" rel="noreferrer">GPU Poet: RTX PRO 5000 價格 (2026-10)</a></li><li><a href="https://www.shidirect.com/product/50313203/NVIDIA-RTX-PRO-4500-Blackwell" target="_blank" rel="noreferrer">SHI: RTX PRO 4500 Blackwell</a></li><li><a href="https://www.theregister.com/a/5300622" target="_blank" rel="noreferrer">The Register: DGX Spark 價格</a></li><li><a href="https://www.implicator.ai/nvidia-adds-64gb-dgx-spark-at-4-999-as-128gb-model-climbs-to-6-950" target="_blank" rel="noreferrer">implicator: NVIDIA adds 64GB DGX Spark</a></li><li><a href="https://acecloud.ai/blog/nvidia-dgx-spark-price/" target="_blank" rel="noreferrer">AceCloud: NVIDIA DGX Spark price</a></li><li><a href="https://www.issoh.co.jp/tech/details/9498/" target="_blank" rel="noreferrer">issoh: GB10 機種價格與評測</a></li><li><a href="https://www.techbang.com/posts/125918-asus-gx10-mini-pc-nvidia-gb10" target="_blank" rel="noreferrer">Techbang: ASUS GX10</a></li><li><a href="https://macworld.com/article/3220024/apple-announces-the-m5-ultra-mac-studio-with-up-to-512gb-of-ram.html" target="_blank" rel="noreferrer">Macworld: Mac Studio M5 Ultra</a></li><li><a href="https://mrmad.com.tw/apple-mac-studio-2026-specs-price" target="_blank" rel="noreferrer">mrmad: Mac Studio 2026 規格與價格</a></li><li><a href="https://www.notebookcheck.net/Apple-increases-RAM-upgrade-pricing-for-M3-Ultra-Mac-Studio-retires-512-GB-option.1244246.0.html" target="_blank" rel="noreferrer">Notebookcheck: M3 Ultra Mac Studio 停售 512GB 選項</a></li><li><a href="https://www.starryhope.com/minipcs/strix-halo-local-llm-inference-2026/" target="_blank" rel="noreferrer">starryhope: Strix Halo local LLM inference 2026</a></li><li><a href="https://www.notebookcheck.net/Framework-Desktop-now-cost-up-to-460-more-due-to-RAM-shortage.1203235.0.html" target="_blank" rel="noreferrer">Notebookcheck: Framework Desktop 因 RAM 短缺漲價</a></li><li><a href="https://computingforgeeks.com/arc-pro-b70-vs-r9700/" target="_blank" rel="noreferrer">ComputingForGeeks: Arc Pro B70 vs R9700</a></li></ul>',25)])])}const k=r(l,[["render",o]]);export{b as __pageData,k as default};
